import numpy as np
from scipy.optimize import least_squares

_params = None

def _response(p, u, h):
    af, tf, a_s, ts = p
    return u * (af * (-np.expm1(-h / tf)) - a_s * (-np.expm1(-h / ts)))

def fit(train_rows):
    global _params
    u = np.array [float(r['u_now']) for r in train_rows]
    h = np.array([float(r['H']) for r in train_rows])
    y = np.array([float(r['y']) for r in train_rows])
    def residual(p):
        return _response(p, u, h) - y
    best = None
    for tf in (0.3, 1.0, 2.0):
        for ts in (5.0, 15.0, 30.0):
            result = least_squares(residual, [2.0, tf, 3.0, ts], bounds=([0.0, 0.001, 0.0, 0.001], [100.0, 1000.0, 100.0, 1000.0]), max_nfev=10000)
            if best is None or np.linalg.norm(result.fun) < np.linalg.norm(best.fun):
                best = result
    _params = best.x

def predict(row):
    return float(_response(_params, float(row['u_now']), float(row['H'])))
